/** Fallback khi không nhận diện được ngân hàng sao kê. */
export const DEFAULT_BANK_DEPOSIT_ACCOUNT_CODE = '11217';

/** TCB FM06 — được định khoản 11217 cả trước cutover 2026. */
export const EARLY_TCB_ACCOUNT_NUMBER = '505566';

/** Template parse (mb/tcb/tpb/vp) → HTTK tiền gửi. */
export const BANK_TEMPLATE_TO_GL: Record<string, string> = {
  mb: '11212',
  tcb: '11217',
  tpb: '11218',
  vp: '11219',
  vpb: '11219',
};

/** STK công ty đã seed → HTTK (import tay + seed). */
export const COMPANY_STK_TO_GL: Record<string, string> = {
  '2839386868': '11212',
  '565566': '11217',
  '515566': '11217',
  '595566': '11217',
  '505566': '11217',
  '525566': '11217',
  '585566': '11217',
  '545566': '11217',
  '1041150736': '11217',
  '398329643': '11219',
};

export interface SaoKeSourceBankHeader {
  accountNumber?: string;
  accountName?: string;
  glAccountCode?: string;
  earlyTcb?: boolean;
}

export function formatSaoKeSourceBankLabel(header: SaoKeSourceBankHeader): string {
  const stk = (header.accountNumber ?? '').trim();
  const name = (header.accountName ?? '').trim();
  if (stk && name) return `TK gửi ${stk} · ${name}`;
  if (stk) return `TK gửi ${stk}`;
  if (name) return `TK gửi ${name}`;
  return '';
}

const BANK_BLOB_TO_GL: Array<{ test: RegExp; gl: string; name: string }> = [
  { test: /\bTPB\b|TPBank|Tiên Phong|11218/i, gl: '11218', name: 'Pháp nhân' },
  { test: /\bVPB\b|VPBank|11219/i, gl: '11219', name: 'Pháp nhân' },
  { test: /\bMB\b|MB Bank|11212/i, gl: '11212', name: 'Pháp nhân' },
  { test: /\bTCB\b|Techcombank|11217/i, gl: '11217', name: 'Pháp nhân' },
];

export function parseSaoKeSourceBankHeader(
  ...parts: Array<string | undefined | null>
): SaoKeSourceBankHeader {
  const blob = parts.filter(Boolean).join(' · ');
  let accountNumber: string | undefined;
  let accountName: string | undefined;

  const tkGui = blob.match(/TK gửi\s+(\d{6,14})(?:\s*·\s*([^|·]+))?/i);
  if (tkGui) {
    accountNumber = tkGui[1];
    accountName = tkGui[2]?.trim();
  }

  if (!accountNumber) {
    const tkName = blob.match(/TK gửi\s+([^|·\d][^|·]*)/i);
    if (tkName?.[1]) accountName = tkName[1].trim();
  }

  if (!accountNumber) {
    const known = Object.keys(COMPANY_STK_TO_GL).sort((a, b) => b.length - a.length);
    accountNumber = known.find(stk => blob.includes(stk));
  }

  if (accountNumber && !accountName) {
    const after = blob.split(accountNumber)[1] ?? '';
    const nameHit = after.match(/^\s*·\s*([^|·]+)/);
    const candidate = (nameHit?.[1] ?? '').trim();
    if (candidate && !/^[\d.:\\/]+$/.test(candidate) && candidate.length > 2) {
      accountName = candidate;
    }
  }

  let glAccountCode = accountNumber
    ? COMPANY_STK_TO_GL[accountNumber]
    : undefined;
  if (!glAccountCode) {
    const hit = BANK_BLOB_TO_GL.find(x => x.test.test(blob));
    if (hit) {
      glAccountCode = hit.gl;
      accountName ??= hit.name;
    }
  }
  return {
    accountNumber,
    accountName,
    glAccountCode,
    earlyTcb: accountNumber === EARLY_TCB_ACCOUNT_NUMBER,
  };
}

export function resolveBankDepositGlFromRows(
  rows: Array<{ bankTemplateId?: string; importReference?: string }>,
): string | undefined {
  const fromStk = parseSaoKeSourceBankHeader(
    ...rows.map(r => r.importReference),
  ).glAccountCode;
  if (fromStk) return fromStk;

  const counts = new Map<string, number>();
  for (const row of rows) {
    const id = (row.bankTemplateId ?? '').trim().toLowerCase();
    if (!id || id === 'generic' || id === 'gpb') continue;
    const gl = BANK_TEMPLATE_TO_GL[id];
    if (!gl) continue;
    counts.set(gl, (counts.get(gl) ?? 0) + 1);
  }
  let best: string | undefined;
  let n = 0;
  for (const [gl, count] of counts) {
    if (count > n) {
      best = gl;
      n = count;
    }
  }
  return best;
}
